package in.suniye.app;
import android.app.Activity;
import android.content.Intent;
import android.net.Uri;
import android.os.Bundle;
import android.widget.*;
import java.io.File;
public final class MainActivity extends Activity implements ReaderController.Listener {
    public static final String SHOW_READING="in.suniye.app.SHOW_READING";
    private static final int PICK_PHOTO=51,PICK_DOCUMENT=52;
    private VoiceControls voice;private ReaderController reader;private TextView status,transcript,sourceLabel,amountHint;private Button stop,expandSource;private SuniyeApp.Document document;private long renderedVersion=-1;private boolean cleanedPdfs=false;
    private boolean renderedUncertain=false,renderedNeedsOriginal=false,renderedWordHelp=false,renderedReading=false,renderedConsent=false,renderedVoice=false,renderedSlow=false;
    private ReaderController controller(){return SuniyeApp.reader(this);}
    @Override public void onCreate(Bundle b){super.onCreate(b);reader=controller();voice=new VoiceControls(this,reader,this::voiceCommand);document=SuniyeApp.document(this);if(b!=null&&document.file==null){String path=b.getString("pdf");if(path!=null){File saved=new File(path);try{if(saved.getCanonicalPath().startsWith(getCacheDir().getCanonicalPath()+File.separator)&&saved.exists()){document.file=saved;document.count=b.getInt("count");document.page=Math.max(0,Math.min(b.getInt("page"),document.count-1));document.version++;}}catch(Exception ignored){}}}cleanOrphanedPdfs();build();if(b==null)handle(getIntent());}
    private void build(){renderedUncertain=reader.hasUncertainText();renderedNeedsOriginal=reader.needsOriginalAction();renderedWordHelp=reader.isWordHelp();renderedVersion=document.version;renderedReading=reader.hasLast()&&!renderedUncertain;renderedConsent=new Config(this).onlineVoice();renderedVoice=new Config(this).voiceCommandsEnabled();renderedSlow=new Config(this).speed()<.701f;stop=Ui.button(this,"रोकिए",true);stop.setOnClickListener(v->reader.stop());Button speak=Ui.button(this,"बोलिए",false);speak.setContentDescription("बोलिए। आवाज़ से ऐप चलाएँ।");speak.setOnClickListener(v->voice.open());LinearLayout controls=new LinearLayout(this);LinearLayout.LayoutParams stopLayout=new LinearLayout.LayoutParams(0,-2,1);stopLayout.rightMargin=Ui.dp(this,8);controls.addView(stop,stopLayout);if(renderedVoice)controls.addView(speak,new LinearLayout.LayoutParams(0,-2,1));LinearLayout root=Ui.screenWithControls(this,controls);Ui.add(root,Ui.text(this,"सुनिए",28,Ui.INK,true),-2,0);if(!renderedReading&&!renderedUncertain)Ui.add(root,Ui.text(this,"बिल, संदेश और फ़ोटो हिंदी में सुनिए।",24,Ui.INK,true),-2,8);
        if(!renderedReading&&!renderedUncertain)Ui.add(root,parentHelp(),-2,16);
        status=Ui.text(this,"",24,Ui.INK,false);status.setAccessibilityLiveRegion(android.view.View.ACCESSIBILITY_LIVE_REGION_POLITE);Ui.add(root,status,-2,18);
        if(!renderedConsent){Button first=Ui.button(this,"परिवार से सेटिंग करवाएँ",true);first.setOnClickListener(v->startActivity(new Intent(this,SetupActivity.class)));Ui.add(root,first,-2,16);}
        if(renderedUncertain){Button uncertain=Ui.button(this,"सावधानी से सुनिए",false);uncertain.setOnClickListener(v->reader.readUncertainText());Ui.add(root,uncertain,-2,16);}
        if(renderedReading){
        Button again=Ui.button(this,"फिर सुनिए",true);again.setOnClickListener(v->reader.repeat());Ui.add(root,again,-2,16);
        Button slow=Ui.button(this,renderedSlow?"सामान्य गति सुनिए":"धीरे सुनिए",false);slow.setOnClickListener(v->{if(new Config(this).speed()<.701f){new Config(this).setSpeed(.85f);reader.repeat();}else reader.slower();});Ui.add(root,slow,-2,16);
        }
        if(document.file!=null){TextView label=Ui.text(this,"पन्ना "+(document.page+1)+" / "+document.count,24,Ui.INK,true);Ui.add(root,label,-2,16);Button next=Ui.button(this,"अगला पन्ना",false);next.setEnabled(document.page+1<document.count);next.setOnClickListener(v->{document.page++;document.version++;build();readPage();});Ui.add(root,next,-2,12);Button previous=Ui.button(this,"पिछला पन्ना",false);previous.setEnabled(document.page>0);previous.setOnClickListener(v->{document.page--;document.version++;build();readPage();});Ui.add(root,previous,-2,12);}
        if(renderedReading&&renderedNeedsOriginal){Button originalAudio=Ui.button(this,"मूल पाठ सुनिए",false);originalAudio.setOnClickListener(v->reader.readOriginal());Ui.add(root,originalAudio,-2,16);}
        if(renderedWordHelp){Ui.add(root,Ui.text(this,"शब्दों की मदद — सामान्य अर्थ",24,Ui.INK,true),-2,24);Ui.add(root,Ui.text(this,reader.spoken(),24,Ui.INK,false),-2,12);}
        sourceLabel=Ui.text(this,"पढ़ा गया पाठ · चित्र से पहचान में गलती हो सकती है",24,Ui.INK,true);Ui.add(root,sourceLabel,-2,24);
        amountHint=Ui.text(this,"",24,Ui.INK,true);Ui.add(root,amountHint,-2,12);
        transcript=Ui.text(this,reader.displayedText(),26,Ui.INK,false);transcript.setMaxLines(4);transcript.setEllipsize(android.text.TextUtils.TruncateAt.END);transcript.setVisibility(reader.displayedText().isEmpty()?android.view.View.GONE:android.view.View.VISIBLE);Ui.add(root,transcript,-2,24);
        expandSource=Ui.button(this,"पूरा पाठ देखिए",false);expandSource.setTextSize(24);expandSource.setOnClickListener(v->{boolean expand=transcript.getMaxLines()!=Integer.MAX_VALUE;transcript.setMaxLines(expand?Integer.MAX_VALUE:4);transcript.setEllipsize(expand?null:android.text.TextUtils.TruncateAt.END);expandSource.setText(expand?"पाठ छोटा दिखाएँ":"पूरा पाठ देखिए");});Ui.add(root,expandSource,-2,12);
        Button camera=Ui.button(this,"कागज़ पढ़िए",!renderedReading);camera.setOnClickListener(v->startActivity(new Intent(this,CameraActivity.class)));Ui.add(root,camera,-2,16);
        camera.setContentDescription("कागज़ पढ़िए। कैमरे से बिल या कागज़ की फ़ोटो लें।");
        Button photo=Ui.button(this,"फ़ोटो पढ़िए",false);photo.setOnClickListener(v->pick("image/*",PICK_PHOTO));Ui.add(root,photo,-2,16);
        if(!renderedReading&&!renderedUncertain)Ui.add(root,Ui.text(this,"फ़ोन में रखी फ़ोटो चुनें।",24,Ui.INK,false),-2,8);
        Button pdf=Ui.button(this,"फ़ाइल पढ़िए",false);pdf.setOnClickListener(v->pick("application/pdf",PICK_DOCUMENT));Ui.add(root,pdf,-2,16);
        if(!renderedReading&&!renderedUncertain)Ui.add(root,Ui.text(this,"कागज़ की PDF फ़ाइल चुनें। एक पन्ना सुनें।",24,Ui.INK,false),-2,8);
        Button whatsapp=Ui.button(this,"WhatsApp से सुनिए",false);whatsapp.setOnClickListener(v->showWhatsAppHelp());Ui.add(root,whatsapp,-2,16);
        if(renderedReading)Ui.add(root,parentHelp(),-2,16);
        if(renderedReading){Button more=Ui.button(this,"और विकल्प",false);more.setTextSize(24);Button explain=Ui.button(this,"शब्दों का मतलब सुनिए",false);explain.setVisibility(android.view.View.GONE);explain.setOnClickListener(v->reader.explain());more.setOnClickListener(v->{boolean show=explain.getVisibility()!=android.view.View.VISIBLE;explain.setVisibility(show?android.view.View.VISIBLE:android.view.View.GONE);more.setText(show?"विकल्प छिपाएँ":"और विकल्प");});Ui.add(root,more,-2,16);Ui.add(root,explain,-2,12);}
        Button setup=Ui.button(this,"परिवार की सेटिंग",false);setup.setTextSize(24);setup.setOnClickListener(v->startActivity(new Intent(this,SetupActivity.class)));Ui.add(root,setup,-2,28);
        onReaderChanged();}
    private Button parentHelp(){Button help=Ui.button(this,"कैसे चलाएँ? सुनिए",false);help.setTextSize(24);help.setOnClickListener(v->reader.announce("बिल या कागज़ के लिए कागज़ पढ़िए दबाएँ। फोन की फोटो के लिए फोटो पढ़िए। दोबारा सुनने के लिए फिर सुनिए। आवाज़ रोकने के लिए नीचे रोकिए दबाएँ।"));return help;}
    private void voiceCommand(VoiceCommand command){switch(command){case STOP:reader.stop();break;case READ:if(document.file!=null)readPage();else if(reader.hasLast())reader.repeat();else reader.announce("संदेश खोलें, या कागज़ पढ़िए दबाएँ।");break;case REPEAT:reader.repeat();break;case SLOW:reader.slower();break;case EXPLAIN:reader.explain();break;case CAPTURE:case CAMERA:startActivity(new Intent(this,CameraActivity.class));break;case PHOTO:pick("image/*",PICK_PHOTO);break;case DOCUMENT:pick("application/pdf",PICK_DOCUMENT);break;default:reader.announce("फ़ोटो लेने के लिए पहले कागज़ पढ़िए खोलें।");}}
    @Override public void onRequestPermissionsResult(int code,String[] permissions,int[] results){super.onRequestPermissionsResult(code,permissions,results);voice.permissionResult(code,results);}
    @Override public void onNewIntent(Intent i){super.onNewIntent(i);voice.close();setIntent(i);handle(i);}
    private void pick(String type,int request){reader.stop();try{startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType(type).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION),request);}catch(android.content.ActivityNotFoundException e){reader.announce("फ़ाइल खोलने वाला ऐप नहीं मिला। परिवार के सदस्य से मदद लें।");}}
    @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request!=PICK_PHOTO&&request!=PICK_DOCUMENT)return;if(result!=RESULT_OK||data==null||data.getData()==null)return;String type=request==PICK_DOCUMENT?"application/pdf":"image/*";handle(new Intent(Intent.ACTION_VIEW).setDataAndType(data.getData(),type));}
    private void showWhatsAppHelp(){reader.stop();startActivity(new Intent(this,WhatsAppHelpActivity.class));}
    private void handle(Intent i){
        if((i.getFlags()&Intent.FLAG_ACTIVITY_LAUNCHED_FROM_HISTORY)!=0)return;
        if(SHOW_READING.equals(i.getAction())){clearPdf();build();return;}
        if(!Intent.ACTION_SEND.equals(i.getAction())&&!Intent.ACTION_VIEW.equals(i.getAction()))return;
        final String type=i.resolveType(this);
        if("text/plain".equals(type)){final CharSequence text;try{text=i.getCharSequenceExtra(Intent.EXTRA_TEXT);}catch(RuntimeException error){reader.announce("यह संदेश नहीं खुला। WhatsApp में खोलकर फिर कोशिश करें।");return;}if(text==null||text.toString().trim().isEmpty()){reader.announce("यह संदेश नहीं खुला। WhatsApp में खोलकर फिर कोशिश करें।");return;}clearPdf();build();reader.readText(text.toString());return;}
        final Uri uri;
        try{android.os.Parcelable stream=Intent.ACTION_SEND.equals(i.getAction())?i.getParcelableExtra(Intent.EXTRA_STREAM):null;uri=Intent.ACTION_VIEW.equals(i.getAction())?i.getData():stream instanceof Uri?(Uri)stream:null;}catch(RuntimeException e){reader.announce("यह फ़ाइल नहीं खुली। फ़ोटो या फ़ाइल के बटन से चुनें।");return;}
        if(uri==null||!"content".equals(uri.getScheme())||!("application/pdf".equals(type)||type!=null&&type.startsWith("image/"))){reader.announce("यह फ़ाइल नहीं खोल सकते। फ़ोटो या फ़ाइल के बटन से चुनें।");return;}
        if("application/pdf".equals(type)){clearPdf();long operation=reader.beginDocument();final long version=document.version;final android.content.Context context=getApplicationContext();final SuniyeApp.Document owned=document;reader.readImageForOperation(()->{File file=ImageInput.copyPdf(context,uri);try{int pages=ImageInput.pdfCount(file);android.graphics.Bitmap rendered=ImageInput.pdfPage(file,0);new android.os.Handler(android.os.Looper.getMainLooper()).post(()->{if(!reader.current(operation)||owned.version!=version){file.delete();return;}owned.replace(file,pages);reader.documentChanged();});return rendered;}catch(Exception error){file.delete();throw error;}},operation);}else{clearPdf();build();reader.readImage(()->ImageInput.fromUri(this,uri));}
    }
    private void readPage(){final File file=document.file;final int index=document.page;reader.readImage(()->ImageInput.pdfPage(file,index));}
    @Override protected void onStart(){super.onStart();reader.addListener(this);}
    @Override protected void onStop(){voice.close();reader.removeListener(this);if((reader.busy()||reader.hasAudio())&&!isChangingConfigurations())reader.stop();super.onStop();}
    @Override public void onReaderChanged(){if(status==null)return;cleanOrphanedPdfs();if(renderedUncertain!=reader.hasUncertainText()||renderedNeedsOriginal!=reader.needsOriginalAction()||renderedWordHelp!=reader.isWordHelp()||renderedVersion!=document.version||renderedReading!=(reader.hasLast()&&!reader.hasUncertainText())||renderedConsent!=new Config(this).onlineVoice()||renderedVoice!=new Config(this).voiceCommandsEnabled()||renderedSlow!=(new Config(this).speed()<.701f)){build();return;}getWindow().getDecorView().setKeepScreenOn(reader.busy());status.setText(reader.status());boolean idle=reader.displayedText().isEmpty()&&!reader.busy()&&(reader.status().equals("एक बटन दबाएँ, फिर आराम से सुनें।")||reader.status().equals("पिछला पढ़ना मिटा दिया।"));status.setVisibility(idle?android.view.View.GONE:android.view.View.VISIBLE);stop.setEnabled(true);stop.setAlpha(1f);if(transcript!=null){transcript.setText(reader.displayedText());expandSource.setVisibility(reader.displayedText().isEmpty()?android.view.View.GONE:android.view.View.VISIBLE);transcript.setVisibility(reader.displayedText().isEmpty()?android.view.View.GONE:android.view.View.VISIBLE);sourceLabel.setVisibility(reader.displayedText().isEmpty()?android.view.View.GONE:android.view.View.VISIBLE);String amount=HindiSpeech.currencyHint(reader.displayedText());amountHint.setText(amount.isEmpty()?"":"रकम हिंदी में: "+amount);amountHint.setVisibility(amount.isEmpty()?android.view.View.GONE:android.view.View.VISIBLE);}}
    private void cleanOrphanedPdfs(){if(cleanedPdfs||reader.busy())return;cleanedPdfs=true;File[] files=getCacheDir().listFiles((dir,name)->name.startsWith("document-")&&name.endsWith(".pdf"));if(files!=null)for(File file:files)if(!file.equals(document.file))file.delete();}
    private void clearPdf(){document.clear();}
    @Override protected void onSaveInstanceState(Bundle state){super.onSaveInstanceState(state);if(document.file!=null){state.putString("pdf",document.file.getAbsolutePath());state.putInt("page",document.page);state.putInt("count",document.count);}}
    @Override protected void onDestroy(){voice.close();if(isFinishing())document.clear();super.onDestroy();}
}
